const PAYMENT_DOCUMENT_URL = /^https?:\/\//i;

// Payment H5 closes by navigating to about:blank. Some Android WebViews,
// including Xiaomi HyperOS, report a hash or query on that URL, or skip
// shouldOverrideUrlLoading while still committing the blank document.
export const isPaymentDocumentUrl = (url?: string | null): boolean =>
  typeof url === 'string' && PAYMENT_DOCUMENT_URL.test(url.trim());

export const isPaymentExitUrl = (url?: string | null): boolean => {
  if (typeof url !== 'string') {
    return false;
  }
  const normalized = url.trim().toLowerCase();
  return normalized === 'about:blank' || normalized.startsWith('about:blank');
};

import {
  isPaymentDocumentUrl,
  isPaymentExitUrl,
} from '../src/screens/product-waiting-room/payment-exit-url';

describe('payment exit url', () => {
  it('recognizes the payment document and blank exit urls', () => {
    expect(isPaymentDocumentUrl('https://pay.example/checkout')).toBe(true);
    expect(isPaymentDocumentUrl('about:blank')).toBe(false);
    expect(isPaymentExitUrl('about:blank')).toBe(true);
    expect(isPaymentExitUrl(' about:blank#blocked ')).toBe(true);
    expect(isPaymentExitUrl('about:blank?close=1')).toBe(true);
    expect(isPaymentExitUrl('https://pay.example/about:blank')).toBe(false);
    expect(isPaymentExitUrl(undefined)).toBe(false);
  });
});

